def is_majority(arr, n, x):
    n = int(n)
    if n <= 0:
        return False

    n = min(n, len(arr))
    if n == 0:
        return False

    def lower_bound(target):
        low, high = 0, n
        while low < high:
            mid = (low + high) // 2
            if arr[mid] < target:
                low = mid + 1
            else:
                high = mid
        return low

    def upper_bound(target):
        low, high = 0, n
        while low < high:
            mid = (low + high) // 2
            if arr[mid] <= target:
                low = mid + 1
            else:
                high = mid
        return low

    first = lower_bound(x)
    last = upper_bound(x)
    count = last - first

    return 2 * count > n

