class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        if k == 0:
            return 0

        candidates = []

        for row, limit in zip(grid, limits):
            if limit <= 0:
                continue

            if limit >= len(row):
                candidates.extend(row)
            else:
                candidates.extend(sorted(row, reverse=True)[:limit])

        candidates.sort(reverse=True)
