def magic_square_test(matrix):
    """
    Return True if the given matrix is a magic square.

    A matrix is considered a magic square if it is square and the sums
    of all rows, all columns, and both diagonals are equal.
    """
    try:
        n = len(matrix)
    except TypeError:
        return False

    if n == 0:
        return False

    for row in matrix:
        try:
            if len(row) != n:
                return False
        except TypeError:
            return False

    try:
        magic_sum = sum(matrix[0])

        for i in range(n):
            if sum(matrix[i]) != magic_sum:
                return False
            if sum(matrix[j][i] for j in range(n)) != magic_sum:
                return False

        if sum(matrix[i][i] for i in range(n)) != magic_sum:
            return False

        if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
            return False

    except (TypeError, IndexError):
        return False

    return True


