    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [0] * numberOfUsers

        parsed_events = []
        for event_type, timestamp, data in events:
            t = int(timestamp)
            if event_type == "OFFLINE":
                # Process offline events before message events at the same timestamp.
                parsed_events.append((t, 0, int(data)))
            else:
                parsed_events.append((t, 1, data))

        parsed_events.sort(key=lambda x: (x[0], x[1]))

        for t, kind, payload in parsed_events:
            if kind == 0:
                user = payload
                offline_until[user] = t + 60
            else:
                for token in payload.split():
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1
                    elif token == "HERE":
                        for user in range(numberOfUsers):
                            if offline_until[user] <= t:
                                mentions[user] += 1
                    else:
                        user = int(token[2:])
                        mentions[user] += 1

