class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []

        max_group = max(groups)

        first_index = {}
        ordered_values = []

        for idx, value in enumerate(elements):
            if value not in first_index:
                first_index[value] = idx
                ordered_values.append((idx, value))

        best = [-1] * (max_group + 1)

        for idx, value in ordered_values:
            if value > max_group:
                continue

            for multiple in range(value, max_group + 1, value):
                if best[multiple] == -1:
                    best[multiple] = idx

        return [best[group] for group in groups]
