    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        ans = total_k

        for target in set(nums):
            if target == k:
                continue

            current = 0
            best_gain = 0

            for v in nums:
                if v == target:
                    current += 1
                elif v == k:
                    current -= 1

                if current < 0:
                    current = 0
                if current > best_gain:
                    best_gain = current

